def run(ctx, args):
    num_variants = args.get("num_variants", 5)
    variants = []
    variants.append({"name": "v1", "code": "def balanced_packing(v1, num_packs):\n    num_layers, num_groups = v1.shape\n    assert num_groups % num_packs == 0\n    groups_per_pack = num_groups // num_packs\n    if groups_per_pack == 1:\n        pack_index = torch.arange(num_groups, device=v1.device)\n        rank_in_pack = torch.zeros_like(v1, dtype=torch.int64)\n        return pack_index, rank_in_pack\n    sorted_idx = torch.argsort(v1, dim=-1, descending=True)\n    pack_idx = sorted_idx // groups_per_pack\n    rank_in_pack = sorted_idx % groups_per_pack\n    return pack_idx, rank_in_pack"})
    variants.append({"name": "v2", "code": "def balanced_packing(v2, num_packs):\n    num_layers, num_groups = v2.shape\n    assert num_groups % num_packs == 0\n    groups_per_pack = num_groups // num_packs\n    if groups_per_pack == 1:\n        pack_index = torch.arange(num_groups, device=v2.device)\n        rank_in_pack = torch.zeros_like(v2, dtype=torch.int64)\n        return pack_index, rank_in_pack\n    sorted_idx = torch.argsort(v2, dim=-1, descending=True)\n    pack_idx = sorted_idx // groups_per_pack\n    rank_in_pack = sorted_idx % groups_per_pack\n    pack_weights = torch.zeros(num_packs, device=v2.device)\n    for i in range(num_layers):\n        pack_weights += v2[i*num_groups:(i+1)*num_groups]\n    return pack_idx, rank_in_pack"})
    variants.append({"name": "v3", "code": "def balanced_packing(v3, num_packs):\n    num_layers, num_groups = v3.shape\n    assert num_groups % num_packs == 0\n    groups_per_pack = num_groups // num_packs\n    if groups_per_pack == 1:\n        pack_index = torch.arange(num_groups, device=v3.device)\n        rank_in_pack = torch.zeros_like(v3, dtype=torch.int64)\n        return pack_index, rank_in_pack\n    sorted_idx = torch.argsort(v3, dim=-1, descending=True)\n    pack_idx = sorted_idx // groups_per_pack\n    rank_in_pack = sorted_idx % groups_per_pack\n    for block in range(0, num_layers, 100):\n        end_block = min(block + 100, num_layers)\n        layer_pack_ids = pack_idx[block:end_block].flatten()\n        for p in range(num_packs):\n            mask = layer_pack_ids == p\n            if mask.sum() > 0:\n                pack_weights[p] += v3[block:end_block][mask].sum()\n    return pack_idx, rank_in_pack"})
    return {"variants": variants}
